mapper.sql:
where h.status = 0 and h.del_flag = 0
  and h.latitude between #{minLat} and #{maxLat}
  and h.longitude between #{minLng} and #{maxLng}
  and not exists (select 1 from im_block b
                   where b.member_id = #{viewerId} and b.blocked_member_id = h.member_id)

mapper.select:
select , , 
from roam_hangout h left join ums_member m on m.id = h.member_id

having distance <= #{radius}
order by distance asc
limit #{limit}

select count(1) from (
    select h.id, 
    from roam_hangout h

    having distance <= #{radius}
) t
